export const BOOT_SCRIPT = "(function(){var d=document.documentElement,s;try{s=localStorage}catch(x){s=null}var t=s&&s.getItem('cw-theme');if(t!=='light'&&t!=='dark'){t='light'}d.setAttribute('data-theme',t);if(s&&s.getItem('cw-side')==='off')d.classList.add('cw-side-off');var a=d.getAttribute('data-ann');if(a&&s&&s.getItem('cw-ann-dismissed')===a)d.classList.add('cw-ann-off');})();";
export const BOOT_SCRIPT_SHA256 = "eSWVSXqZ9UJSICkTUYWT5lohfFMUCZsIomqoYj7aToM=";
